fun main() {

        val infiniteSeq = generateSequence(0) { it + 1 }
        val result = infiniteSeq.chunked(4)
        println(result.take(2).toList())

        val size = 7
        val seq = infiniteSeq.take(7)

        val result2 = seq.chunked(3) { it.joinToString("") }
        println(result2.toList())

