            println(window)
        }

        infiniteSeq.take(3500).windowed(2000, 1000, partialWindows = true).forEachIndexed { windowIndex, window ->
            val startElement = windowIndex * 1000
            val elementCount = when (windowIndex) {
                3 -> 500
                2 -> 1500
                else -> 2000
            }
            println(window)
